/* Original, computed physics illustrations. See visual-lab/biophysics/learning-card.md. */
import type React from "react";
import { BLUE, ORANGE, INK, MUTED, He as StandardHe, La } from "./biochemFigures";
const TEAL="#0f766e", RED="#b91c1c", PURPLE="#7c3aed", LINE="#cbd5e1", KBT=4.1;
function He(p:React.ComponentProps<typeof StandardHe>){
 const children=typeof p.children==='string'?p.children.replace(/[A-Za-z0-9α-ωΑ-ΩℓΔΠζτση⟨⟩√][A-Za-z0-9_α-ωΑ-ΩℓΔΠζτση⟨⟩√²³⁺⁻′½‡·–−/().,=+*^ \t%⁻¹-]*/g,m=>'\u2066'+m.trimEnd()+'\u2069'+m.slice(m.trimEnd().length)):p.children;
 return <StandardHe {...p}>{children}</StandardHe>;
}
function Fig({h,label,children}:{h:number;label:string;children:React.ReactNode}){return <svg viewBox={`0 0 480 ${h}`} className="w-full h-auto" role="img" aria-label={label}><title>{label}</title>{children}</svg>;}
function Note({y,children,color=MUTED}:{y:number;children:string;color?:string}){return /[\u0590-\u05ff]/.test(children)?<He x={240} y={y} size={18} color={color}>{children}</He>:<La x={240} y={y} size={18} color={color}>{children}</La>;}
function Panel({y,h,title,color=BLUE,children}:{y:number;h:number;title:string;color?:string;children:React.ReactNode}){return <g transform={`translate(0 ${y})`}><rect x={10} width={460} height={h} rx={14} fill="#f8fafc" stroke={LINE}/><He x={240} y={31} size={20} bold color={color}>{title}</He>{children}</g>;}
function Arrow({x1,y1,x2,y2,color=INK,dash=false}:{x1:number;y1:number;x2:number;y2:number;color?:string;dash?:boolean}){const a=Math.atan2(y2-y1,x2-x1),c=Math.cos(a),s=Math.sin(a);return <g><line x1={x1} y1={y1} x2={x2} y2={y2} stroke={color} strokeWidth={2} strokeDasharray={dash?'5 4':undefined}/><path d={`M${x2-9*c+4*s} ${y2-9*s-4*c} L${x2} ${y2} L${x2-9*c-4*s} ${y2-9*s+4*c}`} fill="none" stroke={color} strokeWidth={2}/></g>;}
type Pt=[number,number];
type Series={points:Pt[];color:string;dash?:boolean;dots?:boolean};
const sample=(f:(x:number)=>number,a:number,b:number,n=180):Pt[]=>Array.from({length:n+1},(_,i)=>{const x=a+(b-a)*i/n;return [x,f(x)];});
const path=(p:Pt[])=>p.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)} ${y.toFixed(2)}`).join(' ');
const seq=(n:number)=>Array.from({length:n},(_,i)=>i);
function rng(seed:number){let a=seed>>>0;return ()=>{a=(1664525*a+1013904223)>>>0;return (a+.5)/4294967296;};}
function normal(r:()=>number){return Math.sqrt(-2*Math.log(r()))*Math.cos(2*Math.PI*r());}
function Plot({y=0,xmin,xmax,ymin=0,ymax,xt,yt,xlabel,ylabel,series,logx=false,logy=false,marks=[]}:{y?:number;xmin:number;xmax:number;ymin?:number;ymax:number;xt:(number|string)[][];yt:(number|string)[][];xlabel:string;ylabel:string;series:Series[];logx?:boolean;logy?:boolean;marks?:{x:number;y:number;color:string}[]}){
 const tx=(v:number)=>logx?Math.log10(v):v,ty=(v:number)=>logy?Math.log10(v):v;
 const sx=(v:number)=>88+352*(tx(v)-tx(xmin))/(tx(xmax)-tx(xmin));
 const sy=(v:number)=>244-196*(ty(v)-ty(ymin))/(ty(ymax)-ty(ymin));
 return <g transform={`translate(0 ${y})`}><La x={264} y={23} size={19}>{ylabel}</La><path d="M88 44 V244 H444" fill="none" stroke={INK} strokeWidth={1.5}/>
 {xt.map(([v,t])=><g key={v}><line x1={sx(Number(v))} x2={sx(Number(v))} y1={244} y2={250} stroke={INK}/><La x={sx(Number(v))} y={272} size={16}>{t}</La></g>)}
 {yt.map(([v,t])=><g key={v}><line x1={82} x2={88} y1={sy(Number(v))} y2={sy(Number(v))} stroke={INK}/><La x={73} y={sy(Number(v))+6} anchor="end" size={16}>{t}</La></g>)}
 {series.map((s,i)=>{const p=s.points.filter(([x,v])=>x>=xmin&&x<=xmax&&v>=ymin&&v<=ymax).map(([x,v])=>[sx(x),sy(v)] as Pt);return <g key={i}><path d={path(p)} fill="none" stroke={s.color} strokeWidth={2.5} strokeDasharray={s.dash?'7 5':undefined}/>{s.dots&&p.map(([x,v],j)=><circle key={j} cx={x} cy={v} r={4} fill={s.color}/>)}</g>;})}
 {marks.map((m,i)=><circle key={i} cx={sx(m.x)} cy={sy(m.y)} r={5} fill="white" stroke={m.color} strokeWidth={2}/>)}
 <La x={264} y={305} size={19}>{xlabel}</La></g>;
}
function DNA({x=40,y,w=400,open=false}:{x?:number;y:number;w?:number;open?:boolean}){return <g>{[0,1].map(j=><path key={j} d={path(sample(t=>y+(open?12:8)*Math.sin(t/14+j*Math.PI),x,x+w,100))} fill="none" stroke={j?TEAL:BLUE} strokeWidth={3}/>)}{seq(Math.floor(w/10)).map(i=>{const xx=x+i*10;return <line key={i} x1={xx} x2={xx} y1={y+8*Math.sin(xx/14)} y2={y-8*Math.sin(xx/14)} stroke={LINE} strokeWidth={1.4}/>;})}</g>;}
function Polymerase({x,y,color=PURPLE}:{x:number;y:number;color?:string}){return <g transform={`translate(${x} ${y})`}><path d="M-37 13 C-53-9-31-37-8-27 C9-45 41-21 36-4 L14 0 L7 15 L30 22 C10 43-25 38-37 13Z" fill={color} fillOpacity={.18} stroke={color} strokeWidth={2.5}/><path d="M-12-8 L8 0 L2 15" fill="none" stroke={color} strokeWidth={3}/><circle cx={3} cy={7} r={3} fill={RED}/></g>;}
function Head({x,y,color}:{x:number;y:number;color:string}){return <path d={`M${x-18} ${y+8} C${x-28} ${y-11} ${x-8} ${y-24} ${x+7} ${y-17} Q${x+26} ${y-20} ${x+23} ${y-1} L${x+11} ${y+12}Z`} fill={color} stroke={color} strokeWidth={2}/>;}
function Microtubule({y}:{y:number}){return <g>{seq(13).map(i=><g key={i}>{[0,17].map((d,j)=><rect key={j} x={35+i*31} y={y+d} width={29} height={16} rx={6} fill={j?'#a7f3d0':'#6ee7b7'} stroke={TEAL}/>)}</g>)}<La x={452} y={y+24} size={19}>+</La><La x={22} y={y+24} size={19}>−</La></g>;}

function CellScales(){const rows:[string,string,number,number][]=[['מים','0.3 nm',.3,.3],['DNA — קוטר','2 nm',2,2],['חלבון','5 nm',5,5],['ריבוזום','20 nm',20,20],['חיידק — רוחב ואורך','1–2 μm',1000,2000],['תא אאוקריוטי','20 μm',20000,20000]];const sx=(v:number)=>62+370*(Math.log10(v/.1)/6);return <Fig h={665} label="סולם גדלים לוגריתמי ממים עד תא אאוקריוטי"><Note y={28}>סולם לוגריתמי · כל מרווח שווה הוא פי עשרה</Note><path d="M62 70 H432" stroke={INK} strokeWidth={2}/>{[.1,1,10,100,1000,10000,100000].map(v=><g key={v}><line x1={sx(v)} x2={sx(v)} y1={65} y2={78} stroke={INK}/><La x={sx(v)} y={101} size={15}>{v>=1000?`${v/1000} μm`:`${v}`}</La></g>)}<La x={240} y={128} size={17}>0.1–100 nm | 1–100 μm</La>{rows.map(([name,value,a,b],i)=><g key={name}><He x={155} y={165+i*60} size={19} bold>{name}</He><La x={356} y={165+i*60} size={18}>{value}</La><line x1={62} x2={432} y1={184+i*60} y2={184+i*60} stroke={LINE}/><line x1={sx(a)} x2={sx(b)+1} y1={184+i*60} y2={184+i*60} stroke={BLUE} strokeWidth={7}/></g>)}<Note y={550}>בנפח חיידק · קירוב של סדר גודל</Note><La x={240} y={587} bold size={22}>1 molecule ≈ 1 nM in 1 fL</La><Note y={626}>בחישוב מדויק: מולקולה אחת היא כ־1.7 ננומולר</Note></Fig>;}
function EnergyLadder(){const rows:[string,number,number][]=[['קשר מימן במים',1,4],['יציבות זוג בסיסים',1,4],['קשירת ליגנד · Kd = 1 nM',20,20],['ATP בתנאי התא',20,20],['קשר קוולנטי C–C',140,140]];return <Fig h={635} label="השוואת אנרגיות ב-kBT בסולם לוגריתמי"><Note y={28}>גודל האנרגיה · סולם לוגריתמי ביחידות kBT</Note>{rows.map(([t,a,b],i)=><g key={t}><He x={240} y={73+i*86} size={20} bold>{t}</He><line x1={70} x2={420} y1={99+i*86} y2={99+i*86} stroke={LINE}/><rect x={70+150*Math.log10(a)} y={92+i*86} width={Math.max(5,150*Math.log10(b/a))} height={14} fill={i===4?RED:BLUE}/><La x={240} y={126+i*86} size={17}>{a===b?`≈ ${a}`:`${a}–${b}`}</La></g>)}<La x={240} y={527} size={21}>kBT ≈ 4.1 pN·nm (298 K)</La><La x={240} y={564} size={20}>RT ≈ 0.59 kcal/mol</La><Note y={603}>קשירת ליגנד: אנרגיה חופשית ביחס ל־1 מולר</Note></Fig>;}
const well=(x:number)=>3*(x*x-1)**2;
function PotentialWell(){const sx=(x:number)=>240+125*x,sy=(v:number)=>260-38*v;return <Fig h={625} label="נוף אנרגיה עם מינימום יציב ומקסימום לא יציב, קירוב הרמוני ורוחב תרמי"><La x={240} y={30} size={20}>F = −dU/dx</La><path d="M45 275 H445 M55 275 V65" fill="none" stroke={INK} strokeWidth={1.5}/><La x={33} y={77} size={18}>U</La><La x={444} y={307} size={18}>x</La><path d={path(sample(x=>well(x),-1.5,1.5).map(([x,v])=>[sx(x),sy(v)]))} fill="none" stroke={BLUE} strokeWidth={3}/><path d={path(sample(x=>12*(x+1)**2,-1.4,-.6).map(([x,v])=>[sx(x),sy(v)]))} fill="none" stroke={ORANGE} strokeWidth={2} strokeDasharray="6 5"/><Arrow x1={70} y1={188} x2={100} y2={222} color={TEAL}/><Arrow x1={156} y1={218} x2={129} y2={240} color={TEAL}/><Arrow x1={216} y1={133} x2={184} y2={149} color={RED}/><Arrow x1={264} y1={133} x2={296} y2={149} color={RED}/><He x={240} y={83} size={19} color={RED}>מקסימום · לא יציב</He><He x={115} y={329} size={19} color={TEAL}>מינימום יציב</He><La x={365} y={329} size={18}>x₀</La><Panel y={355} h={250} title="סביב מינימום: קפיץ הרמוני" color={ORANGE}><La x={240} y={78} size={21}>U − U₀ ≈ ½k(x − x₀)²</La><Note y={116}>כתום מקווקו: הקירוב ליד המינימום השמאלי</Note><La x={240} y={158} size={21}>σ = √(kBT/k) = √41 ≈ 6.4 nm</La><La x={240} y={197} size={18}>k = 0.1 pN/nm</La><Note y={229}>הנוף העליון סכמטי; חצים מציינים כוח במורד</Note></Panel></Fig>;}
function TwoState(){return <Fig h={590} label="הסתברות פתיחה מחושבת לפי בולצמן ושני בורות אנרגיה"><Plot xmin={-7} xmax={7} ymax={1} xt={[[-5,'−5'],[0,'0'],[5,'+5']]} yt={[[0,'0'],[.5,'0.5'],[1,'1']]} xlabel="ΔG / kBT" ylabel="P_open" series={[{points:sample(x=>1/(1+Math.exp(x)),-7,7),color:BLUE}]} marks={[-5,0,5].map(x=>({x,y:1/(1+Math.exp(x)),color:ORANGE}))}/><La x={240} y={341} size={20}>P_open = 1 / (1 + exp(ΔG/kBT))</La><La x={240} y={378} size={18}>−5: 0.993 | 0: 0.500 | +5: 0.0067</La><path d="M74 468 Q130 552 184 468 Q240 426 295 468 Q350 552 407 468" stroke={BLUE} strokeWidth={2.5} fill="none"/><He x={130} y={561} size={20}>סגור</He><He x={350} y={561} size={20}>פתוח</He><Note y={413}>שני מצבים · בורות סכמטיים</Note></Fig>;}
function ForceTilt(){const base=(x:number)=>400*((x/15)*(1-x/15))**2+40*(3*(x/15)**2-2*(x/15)**3);return <Fig h={890} label="כוח מטה נוף אנרגיה; פתיחת סיכה עם 40 kBT ו-15 ננומטר"><Note y={28}>כוח חיובי מוזיל את המצב המוארך</Note><Plot y={38} xmin={0} xmax={15} ymin={-20} ymax={65} xt={[[0,'0'],[7.5,'7.5'],[15,'15']]} yt={[[-20,'−20'],[0,'0'],[40,'40'],[60,'60']]} xlabel="x (nm)" ylabel="U_eff / kBT" series={[0,8,16].map((f,i)=>({points:sample(x=>base(x)-f*x/KBT,0,15),color:[MUTED,BLUE,ORANGE][i]}))}/><Note y={385}>אפור: בלי כוח · כחול: 8 · כתום: 16 פיקוניוטון</Note><Note y={419}>פרופיל מעבר סכמטי; ההטיה מחושבת לפי ‎−Fx</Note><Plot y={441} xmin={8} xmax={14} ymax={1} xt={[[8,'8'],[10,'10'],[12,'12'],[14,'14']]} yt={[[0,'0'],[.5,'0.5'],[1,'1']]} xlabel="F (pN)" ylabel="P_open" series={[{points:sample(f=>1/(1+Math.exp(40-f*15/KBT)),8,14),color:BLUE}]} marks={[{x:40*KBT/15,y:.5,color:ORANGE}]}/><La x={240} y={797} size={20}>ΔG₀ = 40 kBT | Δx = 15 nm</La><La x={240} y={839} size={21}>F½ = 40 × 4.1 / 15 = 10.93 pN</La></Fig>;}
function BindingCurve(){return <Fig h={550} label="עקומת קשירה לוגריתמית עם Kd של 10 ננומולר והשוואת היל"><Plot xmin={.01} xmax={100} ymax={1} logx xt={[[.01,'0.01'],[.1,'0.1'],[1,'1'],[10,'10'],[100,'100']]} yt={[[0,'0'],[.1,'0.1'],[.5,'0.5'],[.9,'0.9'],[1,'1']]} xlabel="c / Kd (log)" ylabel="p_bound" series={[{points:sample(z=>{const c=10**z;return c/(1+c);},-2,2).map(([z,v])=>[10**z,v]),color:BLUE},{points:sample(z=>1/(1+10**(-3*z)),-2,2).map(([z,v])=>[10**z,v]),color:ORANGE,dash:true}]} marks={[1/9,1,9].map(x=>({x,y:x/(1+x),color:BLUE}))}/><Note y={345} color={BLUE}>כחול רציף: אתר יחיד · היל n = 1</Note><Note y={380} color={ORANGE}>כתום מקווקו: היל n = 3 · אותו חצי־ריכוז</Note><La x={240} y={422} size={21}>p = c/(c + Kd) | Kd = 10 nM</La><La x={240} y={462} size={20}>10%: Kd/9 → 90%: 9Kd | ×81</La><Note y={509}>היל הוא תיאור עקומה; אינו לבדו מנגנון קשירה</Note></Fig>;}
function ChemicalWork(){return <Fig h={690} label="הידרוליזת ATP ועבודה מכנית: תקציב אנרגיה וכוח מרבי"><Note y={29}>תקציב מחזור · לא אנרגיות ביניים שנמדדו</Note><path d="M55 100 H176 V270 H302 V170 H427" fill="none" stroke={BLUE} strokeWidth={4}/><La x={112} y={76} size={20}>G = 0</La><La x={240} y={310} size={20}>ΔG_ATP ≈ −20 kBT</La><La x={363} y={139} size={19}>+F·d ≈ 12 kBT</La><Arrow x1={148} y1={120} x2={148} y2={250} color={BLUE}/><Arrow x1={331} y1={254} x2={331} y2={187} color={ORANGE}/><La x={240} y={350} size={20}>ΔG_cycle = ΔG_ATP + F·d</La><Panel y={380} h={139} title="קינזין · צעד של 8 ננומטר"><La x={240} y={77} size={21}>F_max ≈ (20 × 4.1)/8 ≈ 10 pN</La><Note y={112}>נמדד: כ־6 פיקוניוטון · בעצירה ההספק אפס</Note></Panel><Panel y={533} h={142} title="RNA פולימראז · צעד של זוג בסיסים" color={PURPLE}><La x={240} y={76} size={21}>d = 0.34 nm | 10–20 kBT / NTP</La><Note y={113}>גבול תרמודינמי מעל 100 פיקוניוטון</Note></Panel></Fig>;}

function Osmosis(){return <Fig h={650} label="אוסמוזה: מים חוצים ממברנה לכיוון המומס ותא דם אדום מתנפח"><Panel y={8} h={335} title="ממברנה מעבירה מים, חוסמת מומס"><path d="M46 75 V250 H434 V75 M237 71 V249 M247 71 V249" stroke={TEAL} strokeWidth={3} fill="none"/>{seq(25).map(i=><circle key={i} cx={275+(i%5)*29} cy={96+Math.floor(i/5)*30} r={5} fill={ORANGE}/>)}{[110,175,216].map(y=><Arrow key={y} x1={141} y1={y} x2={218} y2={y} color={BLUE}/>)}<He x={135} y={285} size={20}>מים</He><He x={344} y={285} size={20}>מומס</He><Note y={318}>כחול: זרימת מים נטו לצד המומס</Note></Panel><La x={240} y={387} size={22}>Π = c·kBT = c_molar·RT</La><La x={240} y={427} size={20}>1 mM ≈ 2.5 kPa | 300 mOsm ≈ 7.5 atm</La><path d="M68 511 C70 465 153 465 155 511 C150 548 73 548 68 511Z M88 509 Q112 489 136 509 Q112 529 88 509Z" fill="#fecaca" stroke={RED} strokeWidth={2}/><Arrow x1={188} y1={510} x2={269} y2={510} color={BLUE}/><circle cx={349} cy={510} r={46} fill="#fee2e2" stroke={RED} strokeWidth={2}/><He x={240} y={592} size={20}>תא דם אדום בתמיסה היפוטונית: התנפחות</He><Note y={628}>במים נקיים עלולה להתרחש המוליזה</Note></Fig>;}
function PolymerEntropy(){return <Fig h={680} label="פולימר מכווץ מאפשר צורות רבות; מתיחה מפחיתה אנטרופיה וחימום מגביר כוח מחזיר"><Panel y={8} h={225} title="קצוות קרובים · הרבה צורות"><g>{[0,1,2,3].map(i=><path key={i} d={path(sample(x=>125+28*Math.sin(x/(13+i))+21*Math.cos(x/(22-i)),65,415))} stroke={[BLUE,TEAL,ORANGE,PURPLE][i]} strokeWidth={2.3} fill="none"/>)}</g><Note y={198}>שרשראות חופפות: צורות חלופיות של אותה מולקולה</Note></Panel><Panel y={246} h={182} title="קצוות רחוקים · מעט צורות"><path d={path(sample(x=>97+8*Math.sin(x/17),62,418))} stroke={BLUE} strokeWidth={3} fill="none"/><Arrow x1={138} y1={138} x2={195} y2={138} color={ORANGE}/><Arrow x1={342} y1={138} x2={285} y2={138} color={ORANGE}/><Note y={166}>כתום: כוח מחזיר לכיוון קיצור השרשרת</Note></Panel><La x={240} y={471} size={22}>F = −(3kBT/⟨R²⟩)x | |F| ∝ T</La><Panel y={495} h={168} title="גומי מתוח עם משקולת" color={ORANGE}><path d="M105 60 H175 M140 60 V121 M305 60 H375 M340 60 V99" stroke={MUTED} strokeWidth={3}/><rect x={120} y={121} width={40} height={20} fill={BLUE}/><rect x={320} y={99} width={40} height={20} fill={ORANGE}/><He x={240} y={155} size={18}>בחימום: הכוח האנטרופי גדל, הרצועה מתקצרת</He><La x={91} y={105} size={17}>T</La><La x={375} y={86} size={17}>T ↑</La></Panel></Fig>;}

function RandomWalks(){const colors=[BLUE,ORANGE,TEAL];const walks=colors.map((color,j)=>{const r=rng(134156+j);let x=0;return {color,points:seq(101).map(i=>[i,i?(x+=r()<.5?-1:1):0] as Pt)};});const r=rng(407),paths=colors.map(color=>{let x=240,y=153;return {color,p:seq(91).map(()=>{const a=Math.floor(r()*4)*Math.PI/2;x+=6*Math.cos(a);y+=6*Math.sin(a);return [x,y] as Pt;})};});const bins=(n:number)=>{const a=Array(41).fill(0);for(let j=0;j<2400;j++){let x=0;for(let i=0;i<n;i++)x+=r()<.5?-1:1;const k=Math.floor((x+42)/2);if(k>=0&&k<a.length)a[k]++;}return a;};const hist=[16,100].map(n=>bins(n));return <Fig h={1030} label="הליכות אקראיות מדומות עם זרע קבוע; פיזור נקודות הסיום גדל כשורש מספר הצעדים"><Plot xmin={0} xmax={100} ymin={-25} ymax={25} xt={[[0,'0'],[50,'50'],[100,'100']]} yt={[[-20,'−20'],[0,'0'],[20,'20']]} xlabel="N (steps)" ylabel="x/a (1D)" series={walks}/><Panel y={333} h={300} title="שלוש הליכות במישור · צעדים שווי אורך">{paths.map(s=><path key={s.color} d={path(s.p)} stroke={s.color} strokeWidth={2} fill="none"/>)}<circle cx={240} cy={153} r={4} fill={RED}/><Note y={273}>המסלולים מדומים; הצבעים מבדילים בין חלקיקים</Note></Panel><Panel y={648} h={302} title="היסטוגרמות של נקודות סיום · 2,400 הליכות">{hist.map((a,j)=><g key={j}>{a.map((v,i)=><rect key={i} x={50+i*9} y={234-v/5} width={j?4:8} height={v/5} fill={j?ORANGE:BLUE} opacity={.7}/>)}</g>)}<La x={240} y={267} size={18}>x/a: −40 … 0 … +40</La><Note y={291}>כחול: 16 צעדים · כתום: 100 צעדים</Note></Panel><La x={240} y={994} size={21}>σ/a = √N: 4 → 10</La></Fig>;}
function MSD(){const a:Pt[]=[[.1,.02],[1,.2],[10,2],[100,20]],b:Pt[]=[[.1,.0225],[1,.45],[10,27],[100,2520]];return <Fig h={620} label="MSD לוגריתמי: נתוני שלפוחיות A ו-B מול מודל דיפוזיה וסחיפה"><Plot xmin={.1} xmax={100} ymin={.01} ymax={10000} logx logy xt={[[.1,'0.1'],[1,'1'],[10,'10'],[100,'100']]} yt={[[.01,'0.01'],[1,'1'],[100,'100'],[10000,'10⁴']]} xlabel="Δt (s, log)" ylabel="MSD (μm², log)" series={[{points:sample(z=>.2*10**z,-1,2).map(([z,v])=>[10**z,v]),color:BLUE},{points:sample(z=>.2*10**z+.25*(10**z)**2,-1,2).map(([z,v])=>[10**z,v]),color:ORANGE},{points:sample(z=>.2*(1-Math.exp(-(10**z))),-1,2).map(([z,v])=>[10**z,v]),color:TEAL,dash:true},{points:a,color:BLUE,dots:true},{points:b,color:ORANGE,dots:true,dash:true}]}/><Note y={346} color={BLUE}>A: דיפוזיה · שיפוע 1 · D = 0.1 μm²/s</Note><Note y={384} color={ORANGE}>B: דיפוזיה וסחיפה · שיפוע מתקרב ל־2</Note><La x={240} y={424} size={20}>MSD_B = 0.2Δt + 0.25Δt²</La><Note y={464}>עיגולים: נתוני התרגיל · קווים: מודלים</Note><Note y={504} color={TEAL}>ירוק מקווקו: כליאה · המחשה איכותית לרוויה</Note><Note y={544}>ערכי B יושבים על המודל</Note><La x={240} y={586} size={20}>v = √0.25 = 0.5 μm/s</La></Fig>;}

function FJCWLC(){return <Fig h={913} label="מקטעי FJC לעומת שרשרת WLC; מתאם משיקים ואורכי התמדה"><Panel y={8} h={254} title="מקטעים חופשיים לעומת כיפוף רציף"><La x={77} y={75} size={20}>FJC</La><path d="M130 70 L180 110 L230 70 L280 110 L330 70 L380 110" stroke={BLUE} strokeWidth={3} fill="none"/><La x={235} y={135} size={18}>b</La><La x={77} y={187} size={20}>WLC</La><path d="M130 186 C180 125 220 133 264 181 S355 217 408 169" stroke={ORANGE} strokeWidth={3} fill="none"/><Arrow x1={167} y1={158} x2={206} y2={144} color={TEAL}/><Arrow x1={296} y1={204} x2={338} y2={207} color={TEAL}/><La x={240} y={237} size={19}>b = 2ℓp (L ≫ ℓp)</La></Panel><Plot y={280} xmin={0} xmax={4} ymax={1} xt={[[0,'0'],[1,'1'],[2,'2'],[4,'4']]} yt={[[0,'0'],[.5,'0.5'],[1,'1']]} xlabel="s/ℓp" ylabel="⟨t(s)·t(0)⟩ = exp(−s/ℓp)" series={[{points:sample(x=>Math.exp(-x),0,4),color:ORANGE}]}/><Panel y={624} h={273} title="אורך התמדה · ערכים תלויי תנאים"><He x={142} y={85} size={19}>DNA דו־גדילי</He><La x={351} y={85} size={20}>≈ 50 nm</La><He x={142} y={145} size={19}>אקטין</He><La x={351} y={145} size={20}>≈ 10–17 μm</La><He x={142} y={205} size={19}>מיקרוטובולי</He><La x={351} y={205} size={20}>≈ 1–5 mm</La><Note y={248}>ירוק: משיקים מקומיים · השרשראות סכמטיות</Note></Panel></Fig>;}
function wlc(f:number){let a=0,b=.999999;for(let i=0;i<55;i++){const z=(a+b)/2,force=KBT/50*(1/(4*(1-z)**2)-.25+z);if(force<f)a=z;else b=z;}return (a+b)/2;}
function fjc(f:number){const q=f*100/KBT;return 1/Math.tanh(q)-1/q;}
function ForceExtension(){return <Fig h={655} label="עקומות מחושבות WLC ו-FJC; מתיחת יתר מסומנת בנפרד כסכמה"><Plot xmin={.01} xmax={100} ymax={1} logx xt={[[.01,'0.01'],[.1,'0.1'],[1,'1'],[10,'10'],[100,'100']]} yt={[[0,'0'],[.5,'0.5'],[1,'1']]} xlabel="F (pN, log)" ylabel="x/L" series={[{points:sample(z=>wlc(10**z),-2,2).map(([z,v])=>[10**z,v]),color:BLUE},{points:sample(z=>fjc(10**z),-2,2).map(([z,v])=>[10**z,v]),color:ORANGE,dash:true}]}/><La x={240} y={345} size={20} color={BLUE}>WLC: ℓp = 50 nm | Marko–Siggia</La><La x={240} y={382} size={20} color={ORANGE}>FJC: b = 100 nm | kBT = 4.1 pN·nm</La><Panel y={410} h={226} title="מתיחת־יתר · סמן סכמטי בלבד" color={RED}><La x={240} y={78} size={20}>F ≈ 65 pN | x/L ≈ 1 → 1.7</La><path d="M94 167 L225 150 H385" fill="none" stroke={RED} strokeWidth={3}/><La x={240} y={124} size={18}>F</La><La x={407} y={173} size={18}>x</La><Note y={204}>תלוי בחיבור, במלח ובטמפרטורה</Note></Panel></Fig>;}

function DiffusionSpreading(){const times=[.1,.4,1],D=1;return <Fig h={630} label="גאוסיאנים מחושבים של דיפוזיה בממד אחד בשלושה זמנים"><Plot xmin={-5} xmax={5} ymax={1} xt={[[-4,'−4'],[-2,'−2'],[0,'0'],[2,'2'],[4,'4']]} yt={[[0,'0'],[.5,'0.5'],[1,'1']]} xlabel="x (μm)" ylabel="c / total (μm⁻¹)" series={times.map((t,i)=>({points:sample(x=>Math.exp(-x*x/(4*D*t))/Math.sqrt(4*Math.PI*D*t),-5,5),color:[BLUE,ORANGE,TEAL][i]}))}/><Note y={343}>הדגמה מחושבת: D = 1 μm²/s · שטח כולל זהה</Note><La x={240} y={382} size={20}>t = 0.1, 0.4, 1 s</La><La x={240} y={421} size={21}>σ = √(2Dt) = 0.45, 0.89, 1.41 μm</La><Arrow x1={120} y1={473} x2={62} y2={473} color={BLUE}/><Arrow x1={360} y1={473} x2={418} y2={473} color={BLUE}/><La x={240} y={480} size={21}>J = −D dc/dx</La><Note y={527}>השטף פונה משיא הריכוז אל שני הצדדים</Note><La x={240} y={575} size={18}>c(x,t) = exp(−x²/4Dt) / √(4πDt)</La></Fig>;}
function EinsteinBalance(){const r=rng(1402);return <Fig h={800} label="שיווי משקל שקיעתי: סחיפה מטה ודיפוזיה מעלה; פרופיל בולצמן ויחס איינשטיין"><Panel y={8} h={296} title="x כלפי מעלה · גודל הכוח F כלפי מטה"><path d="M53 63 V251 H224 V63" fill="none" stroke={MUTED} strokeWidth={2}/>{seq(65).map(i=><circle key={i} cx={65+r()*146} cy={247-Math.min(177,-Math.log(r())*51)} r={3} fill={BLUE}/>)}<Arrow x1={272} y1={82} x2={272} y2={210} color={ORANGE}/><Arrow x1={391} y1={210} x2={391} y2={82} color={TEAL}/><He x={272} y={246} size={18} color={ORANGE}>סחיפה</He><He x={391} y={246} size={18} color={TEAL}>דיפוזיה</He><Note y={280}>בשיווי משקל: שטפים שווים והפוכים</Note></Panel><Plot y={325} xmin={0} xmax={4} ymax={1} xt={[[0,'0'],[1,'1'],[2,'2'],[4,'4']]} yt={[[0,'0'],[.5,'0.5'],[1,'1']]} xlabel="Fx/kBT" ylabel="c(x)/c(0) = exp(−Fx/kBT)" series={[{points:sample(x=>Math.exp(-x),0,4),color:BLUE}]}/><La x={240} y={677} size={22}>cF/ζ = −D dc/dx ⇒ D = kBT/ζ</La><La x={240} y={720} size={20}>Stokes: ζ = 6πηa</La><Note y={765}>הסימן תלוי בכיוון הציר; כאן F הוא גודל חיובי</Note></Fig>;}

function FirstPassage(){const D=1,L=10,dt=.05;const series=[0,1,2].map(j=>{const r=rng(417+j);let x=0;const p:Pt[]=[[0,0]];for(let i=1;i<12000;i++){x=Math.abs(x+Math.sqrt(2*D*dt)*normal(r));if(x>=L){p.push([i*dt,L]);break;}p.push([i*dt,x]);}return {color:[BLUE,ORANGE,TEAL][j],points:p};});const max=Math.max(...series.map(s=>s.points.at(-1)![0]));return <Fig h={620} label="מסלולים מדומים עם קיר מחזיר באפס ומטרה בולעת בעשר מיקרומטר"><Plot xmin={0} xmax={max} ymax={10} xt={[[0,'0'],[max/2,(max/2).toFixed(0)],[max,max.toFixed(0)]]} yt={[[0,'0'],[5,'5'],[10,'10']]} xlabel="t (s)" ylabel="x (μm)" series={series} marks={series.map(s=>({x:s.points.at(-1)![0],y:10,color:s.color}))}/><Note y={348}>זרע קבוע · עיגול: פגיעה ראשונה, המסלול נעצר</Note><Panel y={374} h={225} title="אותו אורך ואותו D · תנאי שפה שונים"><La x={240} y={76} size={20}>L = 10 μm | D = 1 μm²/s</La><Note y={115}>מחזיר ב־0, בולע ב־L, התחלה ב־0</Note><La x={240} y={150} size={20}>⟨T⟩ = L²/(2D) = 50 s</La><Note y={183}>שני קצוות בולעים, התחלה באמצע</Note><La x={240} y={213} size={20}>⟨T⟩ = x₀(L−x₀)/(2D) = 12.5 s</La></Panel></Fig>;}
const fact=(n:number):number=>n<=1?1:n*fact(n-1);
const gamma=(t:number,n:number,mean:number)=>{const rate=n/mean;return rate**n*t**(n-1)*Math.exp(-rate*t)/fact(n-1);};
function ExponentialWait(){return <Fig h={810} label="הישרדות והתפלגות המתנה בקצב 5 לשנייה מול גמא בת שלושה שלבים"><Plot xmin={0} xmax={1} ymax={1} xt={[[0,'0'],[.2,'0.2'],[.5,'0.5'],[1,'1']]} yt={[[0,'0'],[.5,'0.5'],[1,'1']]} xlabel="t (s)" ylabel="S(t) = exp(−5t)" series={[{points:sample(t=>Math.exp(-5*t),0,1),color:BLUE}]} marks={[{x:.5,y:Math.exp(-2.5),color:ORANGE}]}/><Plot y={337} xmin={0} xmax={1} ymax={5} xt={[[0,'0'],[.2,'0.2'],[.5,'0.5'],[1,'1']]} yt={[[0,'0'],[2.5,'2.5'],[5,'5']]} xlabel="t (s)" ylabel="p(t) (s⁻¹)" series={[{points:sample(t=>5*Math.exp(-5*t),0,1),color:BLUE},{points:sample(t=>gamma(t,3,.2),0,1),color:ORANGE,dash:true}]}/><Note y={691}>כחול: שלב יחיד · כתום: גמא, שלושה שלבים</Note><La x={240} y={732} size={21}>⟨t⟩ = 1/k = 0.2 s (both)</La><La x={240} y={773} size={20}>S(0.5 s) = exp(−2.5) = 0.082</La></Fig>;}
function Smoluchowski(){const sx=(v:number)=>65+(v-5)*69;return <Fig h={740} label="שטף דיפוזי אל כדור ורמות קצבי אסוציאציה בסולם לוגריתמי"><Panel y={8} h={264} title="מפגש מושלם · כל פגיעה ברדיוס R מגיבה"><circle cx={240} cy={140} r={45} fill="#dbeafe" stroke={BLUE} strokeWidth={2}/><line x1={240} x2={282} y1={140} y2={140} stroke={INK}/><La x={240} y={128} size={19}>R</La>{seq(8).map(i=>{const a=i*Math.PI/4;return <Arrow key={i} x1={240+94*Math.cos(a)} y1={140+94*Math.sin(a)} x2={240+55*Math.cos(a)} y2={140+55*Math.sin(a)} color={TEAL}/>;})}<La x={240} y={255} size={20}>k = 4π(D_A + D_B)R</La></Panel><Note y={316}>קצב אסוציאציה · סולם לוגריתמי</Note><La x={240} y={350} size={19}>k (M⁻¹s⁻¹, log)</La>{[['חלבונים · טיפוסי',5,8,BLUE],['TIM · kcat/Km קרוב לגבול',8,9,ORANGE],['גבול דיפוזיה · סדר גודל',9,10,TEAL]].map(([t,a,b,c],i)=><g key={String(t)}><He x={240} y={398+i*89} size={20} color={String(c)}>{t}</He><line x1={sx(Number(a))} x2={sx(Number(b))} y1={424+i*89} y2={424+i*89} stroke={String(c)} strokeWidth={9}/></g>)}{[5,6,7,8,9,10].map(v=><La key={v} x={sx(v)} y={658} size={16}>{`10${['⁵','⁶','⁷','⁸','⁹','¹⁰'][v-5]}`}</La>)}<Note y={706}>כיוון המפגש ותגובה כימית מורידים את הקצב בפועל</Note></Fig>;}

function ReynoldsScale(){const rows:[string,number][]=[['חיידק',2e-5],['זרעון',2.5e-3],['פרמציום',.2],['דג קטן',100],['אדם שוחה',1e6]];const sx=(r:number)=>65+350*(Math.log10(r)+5)/11;return <Fig h={700} label="מספרי ריינולדס מחושבים לפי גדלים ומהירויות בטקסט"><La x={240} y={32} size={22}>Re = ρvL/η</La><Note y={68}>כל שורה משתמשת באותו סולם לוגריתמי</Note>{rows.map(([t,r],i)=><g key={t}><He x={140} y={119+i*93} size={21} bold>{t}</He><La x={350} y={119+i*93} size={19}>{r===1e6?'10⁶':r===2e-5?'2 × 10⁻⁵':r===.0025?'2.5 × 10⁻³':r}</La><line x1={65} x2={415} y1={147+i*93} y2={147+i*93} stroke={LINE}/><circle cx={sx(r)} cy={147+i*93} r={7} fill={r<1?TEAL:ORANGE}/></g>)}{[-5,-3,0,3,6].map(p=><La key={p} x={sx(10**p)} y={577} size={16}>{`10${{'-5':'⁻⁵','-3':'⁻³','0':'⁰','3':'³','6':'⁶'}[String(p)]}`}</La>)}<Note y={621}>ירוק: צמיגות דומיננטית · כתום: התמד חשוב</Note><Note y={661}>חיידק מפסיק לדחוף: הגלישה קטנה מאטום</Note></Fig>;}
function Flagellum(){const helix=sample(t=>166+24*Math.sin(t/12),185,437,190);return <Fig h={865} label="שוט סלילי מסתובב יוצר דחף מחיכוך אנאיזוטרופי; מנוע פרוטונים וסיבוב נגדי של גוף החיידק"><Panel y={8} h={326} title="סיבוב סליל ודחף לאורך צירו"><rect x={41} y={124} width={119} height={76} rx={36} fill="#ccfbf1" stroke={TEAL} strokeWidth={2.5}/><path d="M160 162 Q177 138 187 163" fill="none" stroke={ORANGE} strokeWidth={6}/><path d={path(helix)} stroke={BLUE} strokeWidth={5} fill="none"/><circle cx={157} cy={163} r={11} fill={ORANGE}/><Arrow x1={280} y1={239} x2={393} y2={239} color={TEAL}/><He x={340} y={277} size={20} color={TEAL}>דחף</He><path d="M123 121 C161 109 130 69 77 116 M259 128 C283 105 302 117 286 137" stroke={PURPLE} strokeWidth={2.5} fill="none"/><Arrow x1={86} y1={110} x2={77} y2={116} color={PURPLE}/><Arrow x1={292} y1={124} x2={286} y2={137} color={PURPLE}/><Note y={307}>גוף החיידק והשוט מסתובבים בכיוונים מנוגדים</Note></Panel><Panel y={348} h={252} title="קטע סליל · פירוק התנגדות לתנועה"><path d="M150 201 L300 65" stroke={BLUE} strokeWidth={8}/><Arrow x1={220} y1={137} x2={270} y2={184} color={ORANGE}/><Arrow x1={220} y1={137} x2={185} y2={169} color={PURPLE}/><Arrow x1={220} y1={137} x2={235} y2={216} color={TEAL}/><La x={365} y={102} size={20}>ζ⊥ ≈ 2ζ∥</La><Note y={234}>כתום: ניצב · סגול: מקביל · ירוק: שקול</Note></Panel><Panel y={615} h={232} title="המנוע בממברנה · מקור האנרגיה" color={ORANGE}><path d="M52 110 H428 M52 131 H428" stroke={TEAL} strokeWidth={4}/><rect x={198} y={83} width={84} height={72} rx={20} fill="#ffedd5" stroke={ORANGE} strokeWidth={2}/><path d="M240 82 V52" stroke={BLUE} strokeWidth={6}/><Arrow x1={166} y1={71} x2={166} y2={164} color={RED}/><La x={119} y={77} size={22}>H⁺</La><Note y={196}>זרם פרוטונים מניע סיבוב · לא הידרוליזת ATP</Note><Note y={224}>מבנה וגאומטריה סכמטיים, לא בקנה מידה</Note></Panel></Fig>;}
function RunTumble(){const r=rng(109),make=(bias:boolean)=>{let x=100,y=100;return seq(11).map(()=>{const a=r()*2*Math.PI,len=35*(bias&&Math.cos(a)>0?1.5:1),p:[Pt,Pt]=[[x,y],[x+len*Math.cos(a),y+len*Math.sin(a)]];[x,y]=p[1];return p;});};const un=make(false),bi=make(true);return <Fig h={690} label="מסלול ריצה והתהפכות בתמיסה אחידה ובשיפוע מושך"><Panel y={8} h={276} title="תמיסה אחידה · מסלול מדומה">{un.map((p,i)=><g key={i}><path d={path(p.map(([x,y])=>[x+120,y+5]))} stroke={BLUE} strokeWidth={3} fill="none"/><circle cx={p[1][0]+120} cy={p[1][1]+5} r={4} fill={ORANGE}/></g>)}<Note y={250}>כחול: ריצה כ־1 שנייה · כתום: התהפכות כ־0.1 שנייה</Note></Panel><Panel y={299} h={286} title="שיפוע של חומר מושך · ריצות ארוכות במעלה">{bi.map((p,i)=><g key={i}><path d={path(p.map(([x,y])=>[x+120,y+5]))} stroke={TEAL} strokeWidth={3} fill="none"/><circle cx={p[1][0]+120} cy={p[1][1]+5} r={4} fill={ORANGE}/></g>)}<Arrow x1={75} y1={231} x2={410} y2={231} color={PURPLE}/><Note y={267}>כיוון החץ: ריכוז המושך עולה</Note></Panel><Note y={628}>החיידק משווה ריכוזים בזמן, באמצעות זיכרון קצר</Note><Note y={665}>מסלולים להמחשה; אינם מעקב ניסויי</Note></Fig>;}

function OpticalTrap(){return <Fig h={915} label="מלכודת אופטית כקפיץ; שתי מלכודות ו-DNA עם מנוע; בקרת כוח ומיקום"><Panel y={8} h={278} title="לייזר ממוקד · חרוז נמשך למוקד"><path d="M124 68 L219 167 L124 226 H356 L261 167 L356 68Z" fill="#fef3c7" fillOpacity={.65}/><ellipse cx={240} cy={68} rx={116} ry={12} fill="#e0f2fe" stroke={BLUE}/><circle cx={268} cy={165} r={32} fill="#dbeafe" stroke={BLUE} strokeWidth={2}/><path d="M240 122 V210" stroke={ORANGE} strokeWidth={1.5} strokeDasharray="4 5"/><Arrow x1={266} y1={165} x2={243} y2={165} color={RED}/><La x={240} y={254} size={22}>|F| = k·Δx</La><He x={82} y={175} size={18}>מוקד</He><line x1={112} x2={226} y1={169} y2={169} stroke={MUTED}/></Panel><Panel y={301} h={282} title="סידור משקולת · DNA בין שני חרוזים">{[90,390].map(x=><g key={x}><path d={`M${x-45} 77 L${x} 161 L${x+45} 77 M${x-45} 233 L${x} 161 L${x+45} 233`} fill="#fef3c7"/><circle cx={x} cy={161} r={29} fill="#dbeafe" stroke={BLUE} strokeWidth={2}/></g>)}<DNA x={120} y={161} w={240}/><Polymerase x={240} y={151}/><La x={240} y={99} size={20}>DNA + RNAP / helicase</La><Note y={262}>שינוי אורך הידית מזיז חרוז ביחס למלכודת</Note></Panel><Panel y={599} h={143} title="שליטה בכוח" color={TEAL}><Note y={78}>הבקרה מזיזה מלכודת ושומרת Δx קבוע</Note><La x={240} y={117} size={20}>F = constant → measure motion</La></Panel><Panel y={757} h={143} title="שליטה במיקום" color={ORANGE}><Note y={78}>המלכודת קבועה · התקדמות מגדילה עומס</Note><La x={240} y={117} size={20}>trap fixed → Δx ↑ → F ↑</La></Panel></Fig>;}
function PowerSpectrum(){const zeta=6*Math.PI*1e-9*500,fc=.1/(2*Math.PI*zeta);return <Fig h={570} label="ספקטרום לורנציאני מחושב לחרוז ברדיוס חצי מיקרומטר ומלכודת בקשיחות 0.1 פיקוניוטון לננומטר"><Plot xmin={10} xmax={1e5} ymin={1e-4} ymax={1.2} logx logy xt={[[10,'10'],[100,'100'],[1000,'10³'],[10000,'10⁴'],[1e5,'10⁵']]} yt={[[1e-4,'10⁻⁴'],[.01,'0.01'],[1,'1']]} xlabel="f (Hz, log)" ylabel="S(f)/S(0) = fc²/(fc² + f²)" series={[{points:sample(z=>fc**2/(fc**2+(10**z)**2),1,5).map(([z,v])=>[10**z,v]),color:BLUE}]} marks={[{x:fc,y:.5,color:ORANGE}]}/><La x={240} y={348} size={21}>fc = k/(2πζ) ≈ 1.69 kHz</La><La x={240} y={388} size={19}>k = 0.1 pN/nm | a = 0.5 μm</La><La x={240} y={428} size={19}>ζ = 6πηa | η = 10⁻⁹ pN·s/nm²</La><Note y={468}>העיגול: חצי מגובה הספקטרום בנקודת הקיטעון</Note><La x={240} y={517} size={21}>⟨x²⟩ = kBT/k = 41 nm²</La></Fig>;}
function TraceFeatures(){const r=rng(708),level=(t:number)=>t<.8?0:t<1.3?8:t<1.8?16:t<3.7?24:t<4.2?16:t<4.7?24:t<5.2?32:40;const raw=sample(t=>level(t)+.5*t+normal(r)*1.5,0,6,600);const avg=raw.map(([t],i)=>[t,raw.slice(Math.max(0,i-5),i+6).reduce((s,p)=>s+p[1],0)/raw.slice(Math.max(0,i-5),i+6).length] as Pt);return <Fig h={600} label="מסלול סינתטי עם צעדים, השהיות, עצירה, צעד לאחור, רעש וסחיפה"><Plot xmin={0} xmax={6} ymin={-5} ymax={48} xt={[[0,'0'],[2,'2'],[4,'4'],[6,'6']]} yt={[[0,'0'],[16,'16'],[32,'32'],[48,'48']]} xlabel="t (s)" ylabel="x (nm)" series={[{points:raw,color:'#94a3b8'},{points:avg,color:BLUE}]}/><Note y={345}>אפור: דגימות עם רעש · כחול: ממוצע 11 דגימות</Note><La x={240} y={384} size={20}>steps = 8 nm | drift = 0.5 nm/s</La><Note y={424}>עצירה ארוכה: 1.8–3.7 שניות</Note><Note y={464}>צעד לאחור: ב־3.7 שניות · התאוששות: ב־4.2</Note><Note y={504}>זמני שהייה: המקטעים שבין קפיצות</Note><Note y={553}>נתונים סינתטיים עם זרע קבוע · לא תוצאת ניסוי</Note></Fig>;}

function MechanochemicalCycle(){const rows=[['1 · קשירת ATP לראש המוביל',0,0],['2 · עגינת הקטע המקשר',0,0],['3 · הראש האחורי מתקדם 16 ננומטר',16,0],['4 · הידרוליזה ושחרור פוספט',16,0]] as const;return <Fig h={1000} label="מחזור קינזין: שני ראשים בצבעים קבועים, תנועה יד על יד וצעד מרכז מסה של 8 ננומטר">{rows.map(([t,move],i)=><Panel key={i} y={8+i*223} h={210} title={t}><Microtubule y={151}/><Head x={155+move*6} y={134} color={BLUE}/><Head x={203} y={i===3?109:134} color={ORANGE}/><path d={`M${155+move*6} 114 Q${190+move*3} ${i===0?100:78} 203 ${i===3?89:114} M${190+move*3} 92 V63`} fill="none" stroke={PURPLE} strokeWidth={5}/>{i===2&&<Arrow x1={150} y1={71} x2={250} y2={71} color={BLUE}/>}<La x={360} y={88} size={19}>{i===3?'ADP + Pi':i===0?'ATP →':'ATP'}</La></Panel>)}<La x={240} y={937} size={21}>head: 16 nm | motor: 8 nm / ATP</La><Note y={978}>כחול וכתום: זהות הראשים · סגול: קטע מקשר</Note></Fig>;}
function RatchetStroke(){return <Fig h={760} label="מכת כוח לעומת מחגר בראוני; כימיה מספקת הטיה וצריכת אנרגיה"><Panel y={8} h={318} title="מכת כוח · שינוי מבנה מניע ישירות"><path d="M70 220 H413" stroke={TEAL} strokeWidth={5}/><path d="M150 218 L195 116 L216 82 M316 218 L289 116 L309 83" fill="none" stroke={BLUE} strokeWidth={9} strokeLinecap="round"/><Arrow x1={223} y1={155} x2={267} y2={155} color={ORANGE}/><La x={240} y={267} size={20}>ATP → conformational change</La><Note y={302}>שינוי כיוון של זרוע · סכמה מכנית</Note></Panel><Panel y={342} h={318} title="מחגר בראוני · תנודה ולאחריה נעילה"><path d="M60 217 H420" stroke={TEAL} strokeWidth={4}/><path d="M80 156 l20-21 l-12-18 l25-20 l-11-17 l30-16 l-9-15 l31-17" stroke={MUTED} strokeWidth={2.5} fill="none" transform="translate(47 58) rotate(65 130 90)"/><Polymerase x={305} y={192}/><path d="M272 196 V233 H332" stroke={ORANGE} strokeWidth={4} fill="none"/><Arrow x1={197} y1={150} x2={258} y2={150} color={BLUE}/><La x={240} y={268} size={20}>thermal motion + chemical locking</La><Note y={302}>כתום: נעילה שמונעת חזרה לאחר תנודה קדימה</Note></Panel><Note y={704}>בלי אנרגיה חופשית אין תנועה נטו בחום אחיד</Note><Note y={743}>מנועים אמיתיים עשויים לשלב את שני הרעיונות</Note></Fig>;}
function ForceVelocity(){const v=(f:number,atp:number)=>8/(1/(2*atp)+1/(100*Math.exp(-f*2/KBT)));return <Fig h={630} label="מהירות מחושבת ממודל שני שלבים בשני ריכוזי ATP; עצירה ניסויית נפרדת"><Plot xmin={0} xmax={8} ymax={800} xt={[[0,'0'],[2,'2'],[4,'4'],[6,'6'],[8,'8']]} yt={[[0,'0'],[400,'400'],[800,'800']]} xlabel="opposing F (pN)" ylabel="v (nm/s)" series={[1000,10].map((a,i)=>({points:sample(f=>v(f,a),0,8),color:i?ORANGE:BLUE}))} marks={[{x:6,y:0,color:RED},...[0,5].flatMap(f=>[1000,10].map((a,i)=>({x:f,y:v(f,a),color:i?ORANGE:BLUE})))]}/><La x={240} y={347} size={20} color={BLUE}>1 mM ATP: v(0) = 762 | v(5) = 69.5</La><La x={240} y={386} size={20} color={ORANGE}>10 μM ATP: v(0) = 133 | v(5) = 48.6</La><La x={240} y={427} size={18}>v = 8 / [1/(2[ATP]) + exp(2F/4.1)/100]</La><Panel y={455} h={158} title="עצירה נמדדת לעומת מודל חד־כיווני" color={RED}><La x={240} y={76} size={21}>red marker: stall ≈ 6 pN | v = 0</La><Note y={112}>המודל כאן אינו חוזה עצירה בכוח סופי</Note><Note y={143}>נדרש מודל עם צעדים לאחור כדי לתאר עצירה</Note></Panel></Fig>;}
function DwellDistributions(){return <Fig h={550} label="התפלגויות שהייה מחושבות עם ממוצע זהה של עשרים מילישניות"><Plot xmin={0} xmax={80} ymax={.07} xt={[[0,'0'],[20,'20'],[40,'40'],[80,'80']]} yt={[[0,'0'],[.025,'0.025'],[.05,'0.05']]} xlabel="τ (ms)" ylabel="p(τ) (ms⁻¹)" series={[1,2,4].map((n,i)=>({points:sample(t=>gamma(t,n,20),0,80),color:[BLUE,ORANGE,TEAL][i]}))}/><La x={240} y={347} size={20} color={BLUE}>N = 1: exponential | r = 1</La><La x={240} y={386} size={20} color={ORANGE}>N = 2: gamma | r = 0.5</La><La x={240} y={425} size={20} color={TEAL}>N = 4: gamma | r = 0.25</La><La x={240} y={466} size={21}>⟨τ⟩ = 20 ms | rate = N/⟨τ⟩</La><Note y={511}>שלבים שווים ברצף · אז בלבד r = 1/N</Note></Fig>;}

function RNAPRatchet(){return <Fig h={755} label="מחגר RNA פולימראז: תנודות לפני ואחרי הזזה, NTP נועל מצב קדמי"><Panel y={8} h={240} title="לפני ההזזה ⇌ אחרי ההזזה"><DNA x={40} y={148} w={400}/><Polymerase x={140} y={137}/><Polymerase x={339} y={137}/><Arrow x1={193} y1={100} x2={286} y2={100} color={BLUE}/><Arrow x1={286} y1={185} x2={193} y2={185} color={BLUE}/><La x={140} y={219} size={19}>pre</La><La x={339} y={219} size={19}>post</La></Panel><Panel y={263} h={254} title="NTP קושר ונועל את המצב הקדמי" color={ORANGE}><DNA x={40} y={146} w={400}/><Polymerase x={240} y={135}/><path d="M170 144 L233 144 L240 178 L329 201" fill="none" stroke={RED} strokeWidth={3}/><circle cx={254} cy={131} r={7} fill={ORANGE}/><La x={356} y={92} size={20}>NTP</La><Arrow x1={329} y1={100} x2={267} y2={123} color={ORANGE}/><La x={240} y={232} size={21}>1 bp = 0.34 nm / NTP</La></Panel><Panel y={532} h={205} title="כוח משנה את ההטיה בין המצבים"><Note y={79}>כוח מסייע: מעודד מצב קדמי</Note><Note y={121}>כוח נגדי: מעודד חזרה ומאט התקדמות</Note><Note y={164}>כחול וירוק: DNA · אדום: RNA · סגול: RNAP</Note><Note y={193}>סכמטי · המרחק בין הציורים אינו גודל הצעד</Note></Panel></Fig>;}
function Backtracking(){const r=rng(831);let pos=3;const p:Pt[]=[];for(let i=0;i<61;i++){pos=Math.max(0,pos+(r()<.5?-1:1));p.push([i,pos]);}return <Fig h={900} label="נסיגת RNA פולימראז, קצה RNA בולט וחיתוך הצלה; מסלול נסיגה דיפוזי מדומה"><Panel y={8} h={298} title="RNAP נסוג · קצה ה־RNA מחוץ לאתר"><DNA y={139}/><Polymerase x={245} y={130}/><path d="M57 178 H210 L241 142 L250 182 L295 208" fill="none" stroke={RED} strokeWidth={4}/><La x={332} y={221} size={21}>3′</La><Arrow x1={302} y1={74} x2={199} y2={74} color={PURPLE}/><Note y={263}>החלקה לאחור מפרידה את הקצה מהאתר הפעיל</Note></Panel><Panel y={321} h={217} title="חיתוך הקצה הבולט והמשך סינתזה" color={TEAL}><La x={240} y={77} size={21}>GreB (bacteria) | TFIIS (eukaryotes)</La><path d="M106 136 H233 L245 113" stroke={RED} strokeWidth={4} fill="none"/><path d="M289 144 L329 167" stroke={RED} strokeWidth={4} strokeDasharray="6 5"/><La x={367} y={174} size={18}>3′</La><Arrow x1={270} y1={106} x2={278} y2={131} color={TEAL}/><Note y={195}>חיתוך RNA יוצר קצה 3′ חדש באתר הפעיל</Note></Panel><Plot y={560} xmin={0} xmax={60} ymax={Math.max(...p.map(v=>v[1]))+1} xt={[[0,'0'],[30,'30'],[60,'60']]} yt={[[0,'0'],[5,'5'],[10,'10']].filter(([v])=>Number(v)<=Math.max(...p.map(v=>v[1])))} xlabel="random steps (schematic)" ylabel="backtrack depth (bp)" series={[{points:p,color:PURPLE}]}/><Note y={890}>הליכת אקראי מדומה · לא עקומת התאוששות ניסויית</Note></Fig>;}
function Helicases(){return <Fig h={862} label="הליקאזה פסיבית מול פעילה ונתוני קצב פתיחה של X ו-Y מהתרגיל">{[0,1].map(i=><Panel key={i} y={8+i*205} h={191} title={i?'פעילה: מערערת את זוג הבסיסים':'פסיבית: ממתינה להתפרמות'} color={i?ORANGE:BLUE}><path d="M70 120 H279 L410 66 M70 137 H279 L410 175" fill="none" stroke={TEAL} strokeWidth={3}/>{seq(15).map(j=><line key={j} x1={77+j*13} x2={77+j*13} y1={120} y2={137} stroke={LINE} strokeWidth={2}/>)}<path d="M250 92 Q297 74 313 113 L291 147 L258 144Z" fill={i?'#ffedd5':'#dbeafe'} stroke={i?ORANGE:BLUE} strokeWidth={2}/>{i&&<path d="M300 119 L324 111 L317 133Z" fill={ORANGE}/>}<La x={124} y={175} size={18}>ATP → motion</La></Panel>)}<Plot y={437} xmin={0} xmax={12} ymax={220} xt={[[2,'2'],[6,'6'],[10,'10']]} yt={[[0,'0'],[100,'100'],[200,'200']]} xlabel="fork force (pN)" ylabel="unwinding (bp/s)" series={[{points:[[2,20],[6,60],[10,180]],color:BLUE,dots:true},{points:[[2,170],[6,180],[10,190]],color:ORANGE,dots:true},{points:[[0,200],[12,200]],color:MUTED,dash:true}]}/><Note y={787}>כחול: X · כתום: Y · מקווקו: תנועת ssDNA</Note><Note y={827}>נקודות מהתרגיל; קווים מחברים בלבד · X פסיבית יותר</Note></Fig>;}
function Nucleosome(){return <Fig h={845} label="Pol II ממתין לפרישת DNA מהנוקלאוזום; פולימראז עוקב מגביל נסיגה">{[0,1].map(i=><Panel key={i} y={8+i*266} h={251} title={i?'פרישה רגעית מאפשרת צעד קדימה':'DNA כרוך: עצירה ונסיגה'}><DNA x={40} y={145} w={170}/><Polymerase x={i?241:176} y={133}/><ellipse cx={336} cy={142} rx={47} ry={38} fill="#fde68a" stroke={ORANGE} strokeWidth={2}/><path d={i?'M207 145 Q235 90 293 120 C270 168 370 206 383 143 C388 85 298 84 293 133 Q277 177 421 145':'M207 145 Q261 103 294 125 C275 172 366 203 383 143 C388 85 298 84 293 133 Q277 177 421 145'} fill="none" stroke={BLUE} strokeWidth={4}/><Note y={222}>זהב: ליבת היסטונים · כחול: DNA · סגול: Pol II</Note></Panel>)}<Panel y={540} h={218} title="פולימראז עוקב מצמצם מקום לנסיגה" color={TEAL}><DNA y={127}/><Polymerase x={169} y={117} color={TEAL}/><Polymerase x={249} y={117}/><path d="M210 73 V159" stroke={RED} strokeWidth={3}/><Arrow x1={285} y1={81} x2={224} y2={81} color={RED}/><Note y={192}>החסימה מאחור מפחיתה נסיגות ועצירות ארוכות</Note></Panel><Note y={801}>תנודות כריכה הן חלק מהמנגנון · המבנים סכמטיים</Note></Fig>;}

function Transport(){return <Fig h={600} label="זמני תובלה מחושבים לדיפוזיה מול מנוע; חציות ב-0.3 וב-60 מיקרומטר"><Plot xmin={.01} xmax={10000} ymin={1e-6} ymax={1e9} logx logy xt={[[.01,'0.01'],[1,'1'],[100,'10²'],[10000,'10⁴']]} yt={[[1e-6,'10⁻⁶'],[.001,'10⁻³'],[1,'1'],[1000,'10³'],[1e6,'10⁶'],[1e9,'10⁹']]} xlabel="L (μm, log)" ylabel="time (s, log)" series={[{points:sample(z=>(10**z)**2/(6*10),-2,4).map(([z,v])=>[10**z,v]),color:BLUE},{points:sample(z=>(10**z)**2/(6*.05),-2,4).map(([z,v])=>[10**z,v]),color:ORANGE},{points:sample(z=>10**z,-2,4).map(([z,v])=>[10**z,v]),color:TEAL}]} marks={[{x:.3,y:.3,color:ORANGE},{x:60,y:60,color:BLUE}]}/><La x={240} y={348} size={20} color={BLUE}>D = 10 μm²/s → L* = 60 μm</La><La x={240} y={388} size={20} color={ORANGE}>D = 0.05 μm²/s → L* = 0.3 μm</La><La x={240} y={428} size={20} color={TEAL}>motor: v = 1 μm/s → t = L/v</La><La x={240} y={474} size={21}>t_diff = L²/(6D) | L* = 6D/v</La><Note y={518}>עיגולים: אותו זמן לשני המנגנונים</Note><Note y={558}>זמן דיפוזיה הוא סקאלה; אינו זמן הגעה מדויק למטרה</Note></Fig>;}
function HairpinHopping(){const tc=[2,.6,.2],to=[.25,.6,1.6];const traces=tc.map((closed,j)=>{const r=rng(815+j);let t=0,open=false;const p:Pt[]=[[0,0]];while(t<12){const dwell=-Math.log(r())*(open?to[j]:closed),next=Math.min(12,t+dwell);p.push([next,open?8.5:0]);if(next>=12)break;open=!open;t=next;p.push([t,open?8.5:0]);}return p;});return <Fig h={1175} label="שלושה מסלולי סיכה מדומים לפי זמני השהייה בתרגיל ויחס אוכלוסיות לוגריתמי">{traces.map((p,i)=><g key={i}><Panel y={8+i*231} h={217} title={`${13+i} פיקוניוטון · סיכה סגורה או פתוחה`} color={[BLUE,ORANGE,TEAL][i]}><path d={path(p.map(([t,x])=>[62+t*30,135-x*6]))} stroke={[BLUE,ORANGE,TEAL][i]} strokeWidth={2} fill="none"/><La x={240} y={176} size={18}>{`⟨τ_closed⟩ = ${tc[i]} s | ⟨τ_open⟩ = ${to[i]} s`}</La><La x={240} y={204} size={16}>t = 0–12 s | Δextension = 8.5 nm</La></Panel></g>)}<Plot y={717} xmin={12.5} xmax={15.5} ymin={-3.2} ymax={3.2} xt={[[13,'13'],[14,'14'],[15,'15']]} yt={[[-2,'−2'],[0,'0'],[2,'2']]} xlabel="F (pN)" ylabel="ln(P_open/P_closed)" series={[{points:sample(f=>(f-14)*Math.log(8),12.5,15.5),color:PURPLE}]} marks={[13,14,15].map(f=>({x:f,y:(f-14)*Math.log(8),color:PURPLE}))}/><La x={240} y={1070} size={20}>slope = ln(64)/2 = 2.079 pN⁻¹</La><La x={240} y={1108} size={20}>Δx = 4.1 × slope ≈ 8.5 nm | F½ = 14 pN</La><Note y={1150}>מסלולים סינתטיים עם זרע קבוע; ממוצעים הם קלט למודל</Note></Fig>;}

export const BIOPHYSICS_FIGURES:Record<string,{el:()=>React.ReactElement;captionHe:string}>={
 'bp-cell-scales':{el:CellScales,captionHe:'סולם גדלים לוגריתמי. קוטר DNA ואורך תא אינם אותו סוג ממד. המרה מדויקת: מולקולה אחת ב־1 fL היא כ־1.66 nM; כלל האצבע בטקסט הוא סדר גודל.'},
 'bp-energy-ladder':{el:EnergyLadder,captionHe:'אנרגיות אופייניות ביחידות kBT, בטמפרטורת החדר. הטווחים תלויים בהקשר; לקשירת ליגנד מוצג גודל אנרגיה חופשית סטנדרטית, ול־ATP גודל השינוי בתנאי התא.'},
 'bp-potential-well':{el:PotentialWell,captionHe:'נוף המחשה מקורי U=3(x²−1)² ביחידות מנורמלות, וקירוב ריבועי ליד מינימום. חצים מראים את כיוון הכוח. רוחב תרמי מחושב בנפרד מנתוני המלכודת שביחידה.'},
 'bp-two-state':{el:TwoState,captionHe:'הסיגמואיד מחושב מחוק בולצמן עם ΔG=G_open−G_closed. ציור שני הבורות סכמטי ואינו קובע קצבי מעבר.'},
 'bp-force-tilt':{el:ForceTilt,captionHe:'למעלה: פרופיל מעבר להמחשת U−Fx עם הפרש קצוות של 40 kBT ו־15 nm; פרטי המחסום סכמטיים. למטה: הסתברות פתיחה מחושבת מהנתונים האלה. זו דוגמת גוף היחידה, השונה מתרגיל הסיכה שבהמשך.'},
 'bp-binding-curve':{el:BindingCurve,captionHe:'העקומה הכחולה מחושבת מ־c/(c+Kd), עם Kd=10 nM מהתרגיל. כתום: השוואת היל n=3 באותו חצי־ריכוז. ציר הריכוז מנורמל ולוגריתמי.'},
 'bp-chemical-work':{el:ChemicalWork,captionHe:'מדרגת אנרגיה סכמטית להידרוליזה של כ־20 kBT ולעבודה של 6×8 pN·nm; אין כאן מדידה של תתי־שלבים כימיים. RNAP משתמש ב־NTP. בעצירה ההספק המכני אפס, וצריכת אנרגיה יכולה להימשך.'},
 'bp-osmosis':{el:Osmosis,captionHe:'מים זורמים לצד המומס דרך ממברנה חצי חדירה. הלחץ מחושב לפי מספר חלקיקי המומס; 300 mOsm מול מים נקיים נותנים בקירוב 7.5 אטמוספרות. התא והמדורים סכמטיים.'},
 'bp-polymer-entropy':{el:PolymerEntropy,captionHe:'השרשראות החופפות הן צורות אפשריות חלופיות. מתיחה מפחיתה את מספר הצורות, וכוח אנטרופי מחזיר גדל עם הטמפרטורה. דוגמת הגומי מתייחסת לרצועה מתוחה עם משקולת.'},
 'bp-random-walk-paths':{el:RandomWalks,captionHe:'הליכות 1D ו־2D והיסטוגרמות נקודות סיום נוצרו במחולל אקראי עם זרעים קבועים. בכל ציר חד־ממדי הצעדים ±a בלתי תלויים. סטיית התקן התאורטית היא a√N.'},
 'bp-msd-plot':{el:MSD,captionHe:'עיגולים מציגים בדיוק את נתוני A/B בתרגיל. קווים מחושבים עם D=0.1 μm²/s ו־v²=0.25 μm²/s²; נתוני B תואמים את המודל. כליאה מוצגת במודל רוויה להמחשה בלבד.'},
 'bp-fjc-wlc':{el:FJCWLC,captionHe:'FJC מתאר מקטעים ישרים עם מפרקים חופשיים; WLC מתכופף ברציפות. עקומת מתאם המשיקים מחושבת כ־exp(−s/ℓp). אורכי ההתמדה הם הטווחים בטקסט ותלויים בתנאים.'},
 'bp-force-extension':{el:ForceExtension,captionHe:'WLC מחושב בהיפוך נומרי של מרקו–סיגיה עם ℓp=50 nm; FJC לפי פונקציית לנז׳וון עם b=100 nm. אלו מודלים שאינם נמתחים. מתיחת היתר ליד 65 pN מסומנת בנפרד כסכמה תלויה בתנאים.'},
 'bp-diffusion-spreading':{el:DiffusionSpreading,captionHe:'גאוסיאנים מנורמלים מחושבים בשלושה זמנים, להדגמה עם D=1 μm²/s. שטח כל עקומה שווה לאחד על הקו האינסופי, והרוחב גדל כ־√(2Dt). חצי השטף מציינים ירידה בריכוז.'},
 'bp-einstein-balance':{el:EinsteinBalance,captionHe:'ציר x פונה מעלה, ו־F הוא גודל הכוח כלפי מטה. לכן c∝exp(−Fx/kBT), סחיפה מטה מאזנת דיפוזיה מעלה. הסימן שונה כאשר מגדירים כוח חתום לאורך הציר; יחס איינשטיין אינו משתנה.'},
 'bp-first-passage-paths':{el:FirstPassage,captionHe:'סימולציית דיפוזיה עם החזרה באפס ובליעה ב־10 μm; העיגולים הם הפגיעות הראשונות. הנוסחאות מציגות את שני תנאי השפה בתרגיל עם D=1 μm²/s. זמן המסלול הבודד אינו הממוצע התאורטי.'},
 'bp-exponential-wait':{el:ExponentialWait,captionHe:'k=5 s⁻¹ מהתרגיל: הישרדות וצפיפות מחושבות. הגמא המקווקוות מתארת שלושה שלבים שווים, כל אחד בקצב 15 s⁻¹, כך שלשתי הצפיפויות אותו זמן ממוצע של 0.2 שנייה.'},
 'bp-smoluchowski':{el:Smoluchowski,captionHe:'כדור סופג עם רדיוס מפגש R ושטף נכנס; נוסחת הקצב כוללת את סכום מקדמי הדיפוזיה. הטווחים הם סדרי גודל בטקסט; עבור TIM מוצגת יעילות kcat/Km, לעומת קצב אסוציאציה לחלבונים.'},
 'bp-reynolds-scale':{el:ReynoldsScale,captionHe:'סולם Re לוגריתמי מנתוני גוף היחידה והתרגיל: אדם 10⁶, דג 100, פרמציום 0.2, זרעון 0.0025, חיידק 0.00002. צבע מציין את המשטר; הסולם אינו תמונת גדלים של הגופים.'},
 'bp-flagellum-thrust':{el:Flagellum,captionHe:'סכמה מקורית של סליל, גוף ומנוע בממברנה. התנגדות ניצבת גדולה מהמקבילה יוצרת רכיב דחף צירי. המנוע מונע בזרם פרוטונים; הגוף מסתובב בכיוון מנוגד לשוט. החצים בגזרת הפירוק הם רכיבי כוח.'},
 'bp-run-tumble':{el:RunTumble,captionHe:'מסלולי המחשה עם זרעים קבועים. נקודות כתומות מסמנות שינוי כיוון; בנוכחות שיפוע המודל מאריך פי 1.5 את הריצות בכיוון ריכוז עולה, בהתאם לרעיון שבתרגיל. החיידק משווה ריכוזים לאורך זמן.'},
 'bp-optical-trap':{el:OpticalTrap,captionHe:'החרוז נמשך למוקד ופועל כקפיץ בקרבתו. גאומטריית המשקולת נלמדה מסידור מלכודות בספר; כאן מצויר ניסוי DNA עם מנוע, כמתואר ביחידה. שליטה בכוח דורשת משוב המזיז את המלכודת.'},
 'bp-power-spectrum':{el:PowerSpectrum,captionHe:'לורנציאן מנורמל S(f)/S(0), מחושב עם k=0.1 pN/nm, רדיוס 500 nm וצמיגות 10⁻⁹ pN·s/nm². תדירות הקיטעון כ־1.69 kHz; אין נתוני ניסוי בעקומה.'},
 'bp-trace-features':{el:TraceFeatures,captionHe:'מסלול סינתטי: צעדי 8 nm, זמני שהייה, עצירה ארוכה, צעד לאחור, סחיפה ורעש. כחול הוא ממוצע נע, לא מסלול אמת ולא זיהוי צעדים מוסק. הממוצע מטשטש גבולות בזמן.'},
 'bp-mechanochemical-cycle':{el:MechanochemicalCycle,captionHe:'מחזור מפושט עם צבע קבוע לכל ראש. הראש האחורי עובר את שותפו ונע 16 nm; התקדמות המנוע היא 8 nm לכל ATP. קטע מקשר בסגול, טובולין בירוק; תמיד נשמר לפחות ראש קשור בסכמה.'},
 'bp-ratchet-vs-stroke':{el:RatchetStroke,captionHe:'שני קצוות מושגיים: שינוי מבנה המניע תנועה, לעומת תנודה תרמית שנלכדת כימית. בשני המקרים צריכת אנרגיה חופשית דרושה לכיווניות; הסכמות אינן תיאור אטומי של מנוע מסוים.'},
 'bp-force-velocity':{el:ForceVelocity,captionHe:'העקומות מחושבות בדיוק ממודל התרגיל: k₁=2 μM⁻¹s⁻¹, k₂⁰=100 s⁻¹, מרחק למחסום 2 nm, צעד 8 nm. המודל החד־כיווני אינו חוזה עצירה בכוח סופי; כוח העצירה הנמדד מוצג כנתון נפרד.'},
 'bp-dwell-distributions':{el:DwellDistributions,captionHe:'צפיפויות גמא מחושבות לממוצע זהה של 20 ms, עם N=1,2,4 וקצבים N/20 ms⁻¹. N=1 הוא אקספוננציאלי. r=1/N תקף לשלבים שווים ברצף, ללא המסלולים הנוספים המוזכרים ביחידה.'},
 'bp-rnap-ratchet':{el:RNAPRatchet,captionHe:'RNAP מתנודד בין מצבים לפני ואחרי הזזה. NTP יכול להיקשר באתר הפנוי במצב שאחרי ההזזה ולנעול אותו; צעד אחד הוא זוג בסיסים. החצים מציינים תנודות ולא תנועה מכוונת בלי אנרגיה.'},
 'bp-backtracking':{el:Backtracking,captionHe:'בנסיגה קצה 3′ יוצא מהאתר הפעיל בלי קיצור מיידי של ה־RNA. חיתוך RNA המוגבר ב־GreB או TFIIS יוצר קצה חדש באתר ומאפשר המשך. מסלול העומק מדומה, ללא שיוך זמן ניסויי.'},
 'bp-helicase-active-passive':{el:Helicases,captionHe:'סכמה: המתנה להתפרמות לעומת ערעור הזוג הבא. הגרף מציג את שלוש נקודות התרגיל בדיוק, עם קווים מחברים בלבד. מהירות תנועת חד־גדיל 200 nt/s היא קו ייחוס; X פסיבית יותר לפי הנתונים.'},
 'bp-pol-nucleosome':{el:Nucleosome,captionHe:'פולימראז ממתין לפתיחה רגעית של DNA כרוך, ויכול לסגת בזמן ההמתנה. פולימראז עוקב מגביל את הנסיגה ומפחית עצירות ארוכות. מספר הליפופים והמרחקים בציור הם סכמטיים.'},
 'bp-transport-comparison':{el:Transport,captionHe:'זמני דיפוזיה מחושבים כ־L²/6D ב־3D, עם D=10 או 0.05 μm²/s; מנוע במהירות 1 μm/s. החציות הן L*=60 ו־0.3 μm. זו השוואת סקאלות תובלה, ללא זמן טעינה או חיפוש מסילה.'},
 'bp-hairpin-hopping':{el:HairpinHopping,captionHe:'מסלולי שני מצבים סינתטיים עם זמני שהייה אקספוננציאליים לפי ממוצעי התרגיל. ממוצעי מסלול קצר עשויים לסטות מהקלט. הגרף התחתון מחושב מיחסי השהייה 0.125, 1, 8 ונותן Δx≈8.5 nm ו־ΔG₀≈29 kBT.'},
};
